mapper.select:
SELECT rela.*, parts.name as spare_part_name, parts.safety_stock_min, COALESCE(stock.inventory_num,0) as inventory_num FROM tpm_device_spare_parts_rela as rela INNER JOIN (SELECT code, name, safety_stock_min FROM tpm_spare_parts WHERE del_flag = '0') as parts ON parts.code = rela.spare_part_code LEFT JOIN ( SELECT spare_parts_code, SUM(inventory_num) as inventory_num FROM tpm_spare_parts_stock WHERE del_flag = '0' GROUP BY spare_parts_code ) as stock ON rela.spare_part_code = stock.spare_parts_code
1=1
AND rela.device_code = #{query.deviceCode}
